#include <string>
#include <vector>

struct SectionFacts { std::string name; double entropy; bool write; bool execute; };
struct Facts { std::vector<SectionFacts> sections; int importCount; std::string entrySection; bool hasDebugInfo; };

std::vector<std::string> triageFlags(const Facts& f)
{
    std::vector<std::string> flags;
    if (f.importCount == 0) flags.push_back("no imports");
    else if (f.importCount < 10) flags.push_back("few imports");
    bool highEntropy{ false };
    for (const SectionFacts& s : f.sections)
        if (s.entropy > 7.2) { flags.push_back("high entropy: " + s.name); highEntropy = true; }
    for (const SectionFacts& s : f.sections)
        if (s.write && s.execute) flags.push_back("writable code: " + s.name);
    if (f.entrySection != ".text") flags.push_back("entry outside .text");
    if (highEntropy && f.importCount < 10) flags.push_back("probably packed");
    if (f.hasDebugInfo) flags.push_back("symbols may be available");
    return flags;
}

unitTests:
using S = std::vector<std::string>;
TEST("an ordinary program") {
    const Facts f{ { { ".text", 6.2, false, true }, { ".rdata", 4.8, false, false }, { ".data", 1.9, true, false } }, 140, ".text", true };
    CHECK_EQ(triageFlags(f), (S{ "symbols may be available" }));
}
TEST("a packed program") {
    const Facts f{ { { "UPX0", 0.0, true, true }, { "UPX1", 7.94, true, true }, { ".rsrc", 5.1, false, false } }, 4, "UPX1", false };
    CHECK_EQ(triageFlags(f), (S{ "few imports", "high entropy: UPX1", "writable code: UPX0", "writable code: UPX1", "entry outside .text", "probably packed" }));
}
TEST("edge cases") {
    const Facts none{ { { ".text", 7.21, false, true } }, 0, ".text", false };
    CHECK_EQ(triageFlags(none), (S{ "no imports", "high entropy: .text", "probably packed" }));
    const Facts compressedData{ { { ".text", 6.0, false, true }, { ".data", 7.9, true, false } }, 60, ".text", false };
    CHECK_EQ(triageFlags(compressedData), (S{ "high entropy: .data" }));
    const Facts exact{ { { ".text", 7.2, false, true } }, 10, ".text", false };
    CHECK(triageFlags(exact).empty());
}

